//! Tracing setup, helpers and propagation with the global provider. The global provider and
//! propagator are process-wide, so everything that relies on them runs in one test.
#![cfg(feature = "testing")]

use grow_zipkin as sdk;

use std::collections::HashMap;
use std::time::Duration;

use opentelemetry::trace::{Link, SpanContext, TraceContextExt};
use opentelemetry::{Context, KeyValue};
use sdk::core::{Error, ErrorCode};
use sdk::testing::tracing::MemorySpanExporter;
use sdk::tracing::{
    add_event, current_span_context, current_span_id, current_trace_id, extract, extract_headers,
    inject, inject_headers, otel_layer, record_exception, set_error, trace_fields, traced,
    traced_sync, with_span, with_span_sync, PropagatorKind, SpanKind, SpanOptions, StatusCode,
    TracingConfig,
};
use tracing_subscriber::prelude::*;

fn io(msg: &str) -> std::io::Error {
    std::io::Error::other(msg.to_string())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn global_pipeline() {
    let exporter = MemorySpanExporter::new();
    let handle = exporter
        .init(
            TracingConfig::new("pipeline")
                .with_service_version("1.0.0")
                .with_environment("test")
                .with_resource_attribute("team", "core")
                .with_propagators(vec![
                    PropagatorKind::TraceContext,
                    PropagatorKind::Baggage,
                    PropagatorKind::B3Multi,
                ]),
        )
        .unwrap();
    assert!(format!("{handle:?}").contains("pipeline"));
    assert_eq!(handle.service_name(), "pipeline");
    assert!(current_trace_id().is_none());
    assert!(current_span_id().is_none());
    assert_eq!(trace_fields(), Default::default());
    assert!(trace_fields().to_attributes().is_empty());

    // with_span (async): nesting, attributes, events, ids, correlation fields.
    let (outer_trace, inner_parent) = with_span(
        "outer",
        SpanOptions::default()
            .kind(opentelemetry::trace::SpanKind::Server)
            .attribute(KeyValue::new("a", 1))
            .attributes(
                &[("b".to_string(), serde_json::json!("x"))]
                    .into_iter()
                    .collect(),
            ),
        async {
            let outer_span = current_span_id().unwrap();
            add_event("hello", vec![KeyValue::new("k", "v")]);
            let fields = trace_fields();
            assert_eq!(fields.span_id.as_deref(), Some(outer_span.as_str()));
            assert_eq!(fields.to_attributes().len(), 2);
            let mut carrier = HashMap::new();
            inject(&mut carrier);
            assert!(carrier.contains_key("traceparent"));
            assert!(carrier.contains_key("x-b3-traceid"));
            let inner = traced("inner", async {
                Ok::<_, std::io::Error>(current_span_context().unwrap())
            })
            .await?;
            assert_ne!(inner.span_id().to_string(), outer_span);
            Ok::<_, std::io::Error>((current_trace_id().unwrap(), outer_span))
        },
    )
    .await
    .unwrap();

    // Errors set ERROR status and record an exception; the error is returned unchanged.
    let err = with_span("fails", SpanOptions::default(), async {
        Err::<(), _>(io("nope"))
    })
    .await
    .unwrap_err();
    assert_eq!(err.to_string(), "nope");
    let err = traced_sync("fails-sync", || Err::<(), _>(io("sync nope"))).unwrap_err();
    assert_eq!(err.to_string(), "sync nope");
    assert!(with_span_sync("ok-sync", SpanOptions::default(), || {
        set_error(&io("marked"));
        record_exception("just recorded");
        Ok::<_, Error>(current_trace_id().is_some())
    })
    .unwrap());

    // Panics are recorded and resumed (sync and async).
    let caught = std::panic::catch_unwind(|| {
        let _ = with_span_sync("panics", SpanOptions::default(), || -> Result<(), Error> {
            panic!("kaboom")
        });
    });
    assert!(caught.is_err());
    let task = tokio::spawn(with_span("panics-async", SpanOptions::default(), async {
        if true {
            std::panic::panic_any(String::from("async kaboom"));
        }
        Ok::<(), Error>(())
    }));
    assert!(task.await.unwrap_err().is_panic());
    let caught = std::panic::catch_unwind(|| {
        let _ = traced_sync("panics-other", || -> Result<(), Error> {
            std::panic::panic_any(7u8)
        });
    });
    assert!(caught.is_err());

    // Explicit parent, link and tracer.
    let remote = SpanContext::new(
        opentelemetry::trace::TraceId::from_hex("4bf92f3577b34da6a3ce929d0e0e4736").unwrap(),
        opentelemetry::trace::SpanId::from_hex("00f067aa0ba902b7").unwrap(),
        opentelemetry::trace::TraceFlags::SAMPLED,
        true,
        Default::default(),
    );
    with_span(
        "linked",
        SpanOptions::default()
            .parent(Context::new().with_remote_span_context(remote.clone()))
            .link(Link::with_context(remote.clone()))
            .tracer(handle.tracer("custom", Some("9.9.9"))),
        async { Ok::<_, Error>(()) },
    )
    .await
    .unwrap();

    // Extraction: map carrier (case-insensitive) and headers.
    let mut carrier = HashMap::new();
    carrier.insert(
        "TraceParent".to_string(),
        "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01".to_string(),
    );
    let cx = extract(&carrier);
    assert_eq!(
        cx.span().span_context().trace_id().to_string(),
        "4bf92f3577b34da6a3ce929d0e0e4736"
    );
    let mut headers = http::HeaderMap::new();
    {
        let _g = cx.clone().attach();
        inject_headers(&mut headers);
        assert_eq!(
            current_trace_id().as_deref(),
            Some("4bf92f3577b34da6a3ce929d0e0e4736")
        );
    }
    assert!(headers
        .get("traceparent")
        .unwrap()
        .to_str()
        .unwrap()
        .contains("4bf92f35"));
    assert_eq!(headers.get("x-b3-spanid").unwrap(), "00f067aa0ba902b7");
    let back = extract_headers(&headers);
    assert_eq!(back.span().span_context().span_id(), remote.span_id());

    // tracing spans through the tracing-opentelemetry layer are seen by the helpers.
    let subscriber = tracing_subscriber::registry().with(otel_layer(&handle));
    let from_tracing = tracing::subscriber::with_default(subscriber, || {
        let span = tracing::info_span!("tracing-span");
        let _e = span.enter();
        let id = current_trace_id();
        // A helper span started here becomes a child of the tracing span.
        traced_sync("child-of-tracing", || Ok::<_, Error>(())).unwrap();
        id
    });
    assert!(from_tracing.is_some());

    handle
        .force_flush(Some(Duration::from_secs(5)))
        .await
        .unwrap();
    handle.force_flush(None).await.unwrap();
    let spans = exporter.spans();
    let by_name = |n: &str| {
        spans
            .iter()
            .find(|s| s.name == n)
            .unwrap_or_else(|| panic!("{n}"))
    };
    let outer = by_name("outer");
    assert_eq!(outer.trace_id, outer_trace);
    assert_eq!(outer.kind, SpanKind::Server);
    assert_eq!(outer.attributes["a"], 1);
    assert_eq!(outer.attributes["b"], "x");
    assert_eq!(outer.events[0].name, "hello");
    assert_eq!(
        by_name("inner").parent_span_id.as_deref(),
        Some(inner_parent.as_str())
    );
    let fails = by_name("fails");
    assert_eq!(fails.status.code, StatusCode::Error);
    assert_eq!(fails.status.message.as_deref(), Some("nope"));
    assert_eq!(fails.events[0].attributes["exception.message"], "nope");
    assert_eq!(by_name("fails-sync").status.code, StatusCode::Error);
    let ok_sync = by_name("ok-sync");
    assert_eq!(ok_sync.status.code, StatusCode::Error);
    assert_eq!(ok_sync.events.len(), 2);
    assert_eq!(
        by_name("panics").events[0].attributes["exception.message"],
        "panic: kaboom"
    );
    assert_eq!(
        by_name("panics-async").events[0].attributes["exception.message"],
        "panic: async kaboom"
    );
    assert_eq!(
        by_name("panics-other").events[0].attributes["exception.message"],
        "panic"
    );
    let linked = by_name("linked");
    assert_eq!(linked.trace_id, "4bf92f3577b34da6a3ce929d0e0e4736");
    assert_eq!(linked.parent_span_id.as_deref(), Some("00f067aa0ba902b7"));
    assert_eq!(linked.links.len(), 1);
    let tracing_span = by_name("tracing-span");
    assert_eq!(
        by_name("child-of-tracing").parent_span_id.as_deref(),
        Some(tracing_span.span_id.as_str())
    );
    assert_eq!(exporter.service_name(), "pipeline");
    assert_eq!(outer.service_name, "pipeline");

    // Shutdown is idempotent; spans after shutdown are not exported.
    handle.shutdown().await.unwrap();
    handle.shutdown().await.unwrap();
    assert!(handle.is_shutdown());
    assert_eq!(exporter.shutdown_calls(), 1);
    let err = handle.force_flush(None).await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unavailable);
}
